/*
 * A100552  Single-digit primes, followed recursively by 2k-digit primes
 *          obtained by concatenation of pairs of distinct k-digit primes of
 *          the sequence.
 * https://oeis.org/A100552
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini, full, less
 * Formula:   a(n) is generated by concatenating distinct primes from the
 *            previous level of primes (starting with single‑digit primes
 *            2,3,5,7) and taking the primes that result. The sequence is
 *            finite
 * Range:     u8 n <= 8, u16 n <= 9, u32 n <= 9, u64 n <= 9, u128 n <= 9,
 *            big any n
 * Helpers:   digits, is_prime_uint64, pow10
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/is_prime_uint64.h"
#include "../utils/digits.h"
#include "../utils/pow10.h"

seq_t a(idx_t n)
{
    /* static storage for the whole finite sequence, sorted */
    static seq_t seq[128];
    static idx_t seq_len = 0;          /* number of terms known */

    if (seq_len == 0) {
        /* Level 0: single‑digit primes. They are already sorted. */
        seq[0] = 2;
        seq[1] = 3;
        seq[2] = 5;
        seq[3] = 7;
        seq_len = 4;

        /* current and next level arrays, sorted */
        seq_t curr[64];
        seq_t next[64];
        idx_t curr_len = 4;
        for (idx_t i = 0; i < curr_len; ++i)
            curr[i] = seq[i];

        /* generate subsequent levels until no new primes appear */
        while (true) {
            idx_t next_len = 0;

            /* generate all concatenations of distinct pairs from curr */
            for (idx_t i = 0; i < curr_len; ++i) {
                for (idx_t j = 0; j < curr_len; ++j) {
                    if (i == j)
                        continue;                    /* distinct only */

                    /* cast curr[j] to idx_t for digits and pow10 */
                    idx_t dj = digits((idx_t)(uint64_t)curr[j]);
                    seq_t val = curr[i] * pow10(dj) + curr[j];

                    /* test primality (all values fit in uint64_t) */
                    if (is_prime_uint64((uint64_t)val)) {
                        next[next_len++] = val;
                    }
                }
            }

            if (next_len == 0)
                break;   /* sequence terminates */

            /* sort the newly found primes */
            for (idx_t i = 1; i < next_len; ++i) {
                seq_t key = next[i];
                idx_t j = i;
                while (j > 0 && next[j-1] > key) {
                    next[j] = next[j-1];
                    --j;
                }
                next[j] = key;
            }

            /* insert each new prime into the global sequence, keeping it sorted */
            for (idx_t i = 0; i < next_len; ++i) {
                seq_t val = next[i];
                /* find insertion position */
                idx_t pos = 0;
                while (pos < seq_len && seq[pos] < val)
                    ++pos;

                /* shift elements to make room */
                for (idx_t k = seq_len; k > pos; --k)
                    seq[k] = seq[k-1];
                seq[pos] = val;
                ++seq_len;
            }

            /* prepare for next level */
            curr_len = next_len;
            for (idx_t i = 0; i < curr_len; ++i)
                curr[i] = next[i];
        }
    }

    /* return the requested term if it exists */
    if (n > 0 && n <= seq_len)
        return seq[n-1];

    /* terms beyond the finite sequence are defined as 0 */
    return 0;
}
